import re

def is_slug(text: str) -> bool:
    return isinstance(text, str) and re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*', text) is not None

def chunks(data: bytes, size: int):
    if size <= 0:
        raise ValueError('size must be positive')
    for start in range(0, len(data), size):
        yield data[start:start + size]

from pathlib import Path

def safe_join(root: Path, filename: str) -> Path:
    if not filename or filename in {'.', '..'} or '/' in filename or '\\' in filename:
        raise ValueError('expected a simple filename')
    return root / filename

def ensure_suffix(name: str, suffix: str) -> str:
    if not suffix:
        raise ValueError('suffix must not be empty')
    return name if name.endswith(suffix) else name + suffix

export function sumPositive(values: readonly number[]): number {
  return values.reduce((sum, value) => sum + (Number.isFinite(value) && value > 0 ? value : 0), 0);
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

def count_lines(path):
    with open(path, encoding='utf-8') as stream:
        return sum(1 for _ in stream)

static boolean isAsciiDigit(char ch) {
    return ch >= '0' && ch <= '9';
}

export function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${String(value)}`);
}

def invert_multimap(mapping):
    result = {}
    for key, values in mapping.items():
        for value in dict.fromkeys(values):
            result.setdefault(value, []).append(key)
    return result

def parse_flag(value: str) -> bool:
    token = value.strip(" \t\r\n\v\f").casefold()
    if token in {"yes", "true", "1"}:
        return True
    if token in {"no", "false", "0"}:
        return False
    raise ValueError("invalid flag")

def pairwise(items):
    iterator = iter(items)
    try:
        previous = next(iterator)
    except StopIteration:
        return
    for current in iterator:
        yield previous, current
        previous = current

def parse_key_values(lines):
    result = {}
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError("missing =")
        key, value = line.split("=", 1)
        key = key.strip(" ")
        value = value.strip(" ")
        if not key or key in result:
            raise ValueError("empty or duplicate key")
        result[key] = value
    return result

def take_until(items, predicate):
    for item in items:
        yield item
        if predicate(item):
            return

def choose_best(records, score):
    iterator = iter(records)
    try:
        best = next(iterator)
    except StopIteration:
        raise ValueError("no records") from None
    best_score = score(best)
    for record in iterator:
        candidate_score = score(record)
        if candidate_score > best_score:
            best, best_score = record, candidate_score
    return best

def merge_sorted(left, right):
    sentinel = object()
    left_iter, right_iter = iter(left), iter(right)
    a, b = next(left_iter, sentinel), next(right_iter, sentinel)
    while a is not sentinel and b is not sentinel:
        if a <= b:
            yield a
            a = next(left_iter, sentinel)
        else:
            yield b
            b = next(right_iter, sentinel)
    while a is not sentinel:
        yield a
        a = next(left_iter, sentinel)
    while b is not sentinel:
        yield b
        b = next(right_iter, sentinel)

from collections.abc import Mapping

def get_path(mapping, path, default=None):
    current = mapping
    for key in path:
        if not isinstance(current, Mapping) or key not in current:
            return default
        current = current[key]
    return current

def split_at(items, index):
    if index < 0:
        raise ValueError("negative index")
    before, after = [], []
    for position, item in enumerate(items):
        (before if position < index else after).append(item)
    return before, after

def first_duplicate(items):
    seen = set()
    for item in items:
        if item in seen:
            return item
        seen.add(item)
    return None

def replace_first(text: str, old: str, new: str) -> str:
    if not old:
        raise ValueError("old must not be empty")
    position = text.find(old)
    if position < 0:
        return text
    return text[:position] + new + text[position + len(old):]

from datetime import date

def parse_iso_day(text: str) -> date:
    if len(text) != 10 or text[4] != "-" or text[7] != "-":
        raise ValueError("invalid date")
    digits = text[:4] + text[5:7] + text[8:]
    if len(digits) != 8 or any(ch < "0" or ch > "9" for ch in digits):
        raise ValueError("invalid date")
    return date(int(text[:4]), int(text[5:7]), int(text[8:]))

from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

def url_with_query(base: str, params):
    parts = urlsplit(base)
    existing = parse_qsl(parts.query, keep_blank_values=True)
    query = urlencode(existing + list(params))
    return urlunsplit((parts.scheme, parts.netloc, parts.path, query, parts.fragment))

def count_runs(items):
    iterator = iter(items)
    try:
        current = next(iterator)
    except StopIteration:
        return
    count = 1
    for item in iterator:
        if item == current:
            count += 1
        else:
            yield current, count
            current, count = item, 1
    yield current, count

def require_fields(record, required):
    missing = [key for key in required if key not in record]
    if missing:
        raise ValueError("missing: " + ", ".join(missing))
    return dict(record)

def trim_history(history, limit):
    if limit < 0:
        raise ValueError("negative limit")
    if limit == 0:
        return []
    return list(history[-limit:])

def bounded_sum(values, cap):
    if cap < 0:
        raise ValueError("negative cap")
    total = 0
    for value in values:
        if value < 0:
            raise ValueError("negative value")
        total += value
        if total > cap:
            raise OverflowError("sum exceeds cap")
    return total

def line_numbered(lines, start=1):
    for number, line in enumerate(lines, start):
        if line.endswith("\n"):
            line = line[:-1]
            if line.endswith("\r"):
                line = line[:-1]
        yield f"{number}: {line}"

def unique_by(items, key):
    seen = set()
    for item in items:
        marker = key(item)
        if marker not in seen:
            seen.add(marker)
            yield item

def add_event(event, events=None):
    if events is None:
        events = []
    events.append(event)
    return events

def purge_expired(cache, now):
    expired = [key for key, entry in cache.items() if entry["expires"] <= now]
    for key in expired:
        del cache[key]
    return len(expired)

def read_small(path, max_bytes):
    if max_bytes < 0:
        raise ValueError("negative max_bytes")
    with open(path, "rb") as stream:
        data = stream.read(max_bytes + 1)
    if len(data) > max_bytes:
        raise ValueError("file too large")
    return data

export function partition<T>(items: readonly T[], accept: (item: T) => boolean): [T[], T[]] {
  const yes: T[] = [];
  const no: T[] = [];
  for (const item of items) {
    (accept(item) ? yes : no).push(item);
  }
  return [yes, no];
}

export function zipExact<A, B>(left: readonly A[], right: readonly B[]): Array<[A, B]> {
  if (left.length !== right.length) throw new RangeError("length mismatch");
  return left.map((value, index) => [value, right[index]]);
}

export function maxBy<T>(items: readonly T[], score: (item: T) => number): T | undefined {
  let best: T | undefined;
  let bestScore = -Infinity;
  let found = false;
  for (const item of items) {
    const current = score(item);
    if (!found || current > bestScore) {
      best = item;
      bestScore = current;
      found = true;
    }
  }
  return best;
}

export function pick<T extends object, K extends keyof T>(value: T, keys: readonly K[]): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(value, key)) {
      result[key] = value[key];
    }
  }
  return result;
}

export function assertPresent<T>(value: T | null | undefined, name: string): T {
  if (value === null || value === undefined) throw new Error(name + " is required");
  return value;
}

function interleave(left, right) {
  const result = [];
  const length = Math.max(left.length, right.length);
  for (let index = 0; index < length; index++) {
    if (index < left.length) result.push(left[index]);
    if (index < right.length) result.push(right[index]);
  }
  return result;
}

export function toggle<T>(items: ReadonlySet<T>, value: T): Set<T> {
  const result = new Set(items);
  if (result.has(value)) result.delete(value);
  else result.add(value);
  return result;
}

export function setEquals<T>(left: ReadonlySet<T>, right: ReadonlySet<T>): boolean {
  if (left.size !== right.size) return false;
  for (const value of left) {
    if (!right.has(value)) return false;
  }
  return true;
}

function stableInsert(sorted, value, compare) {
  let low = 0;
  let high = sorted.length;
  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (compare(sorted[middle], value) <= 0) low = middle + 1;
    else high = middle;
  }
  return [...sorted.slice(0, low), value, ...sorted.slice(low)];
}

function binarySearch(sorted, target, compare) {
  let low = 0;
  let high = sorted.length;
  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (compare(sorted[middle], target) < 0) low = middle + 1;
    else high = middle;
  }
  return low < sorted.length && compare(sorted[low], target) === 0 ? low : -1;
}

export async function mapSeries<T, U>(items: readonly T[], fn: (item: T) => Promise<U>): Promise<U[]> {
  const result: U[] = [];
  for (const item of items) {
    result.push(await fn(item));
  }
  return result;
}

export function withTimeout<T>(work: Promise<T>, ms: number): Promise<T> {
  if (!Number.isFinite(ms) || ms < 0) return Promise.reject(new RangeError("invalid timeout"));
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("timeout")), ms);
    work.then(
      value => { clearTimeout(timer); resolve(value); },
      error => { clearTimeout(timer); reject(error); }
    );
  });
}

function parseRgbHex(text) {
  if (typeof text !== "string" || !/^#[0-9a-fA-F]{6}$/.test(text)) {
    throw new Error("invalid RGB hex");
  }
  return {
    r: Number.parseInt(text.slice(1, 3), 16),
    g: Number.parseInt(text.slice(3, 5), 16),
    b: Number.parseInt(text.slice(5, 7), 16)
  };
}

export function isNonNull<T>(value: T | null | undefined): value is T {
  return value !== null && value !== undefined;
}

function removeAt(items, index) {
  if (!Number.isInteger(index)) throw new RangeError("invalid index");
  const position = index < 0 ? items.length + index : index;
  if (position < 0 || position >= items.length) throw new RangeError("invalid index");
  return [...items.slice(0, position), ...items.slice(position + 1)];
}

export function compareTuple(left: readonly number[], right: readonly number[]): number {
  const length = Math.min(left.length, right.length);
  for (let index = 0; index < length; index++) {
    if (left[index] < right[index]) return -1;
    if (left[index] > right[index]) return 1;
  }
  return left.length < right.length ? -1 : left.length > right.length ? 1 : 0;
}

function formatInitials(name) {
  const words = name.trim().split(/\s+/u);
  if (words[0] === "") return "";
  return words.map(word => Array.from(word)[0].toUpperCase()).join("");
}

export function keysWithPrefix<T extends Record<string, unknown>>(value: T, prefix: string): string[] {
  return Object.keys(value).filter(key => key.startsWith(prefix));
}

function addListener(target, type, handler) {
  target.addEventListener(type, handler);
  let active = true;
  return function cleanup() {
    if (!active) return;
    active = false;
    target.removeEventListener(type, handler);
  };
}

async function readJson(url: string): Promise<unknown> {
  const response = await fetch(url);
  if (!response.ok) throw new Error("HTTP " + response.status);
  return response.json();
}

static byte[] decodeHex(String text) {
    if ((text.length() & 1) != 0) throw new IllegalArgumentException("odd hex length");
    byte[] result = new byte[text.length() / 2];
    for (int i = 0; i < text.length(); i += 2) {
        char a = text.charAt(i);
        char b = text.charAt(i + 1);
        int high = Character.digit(a, 16);
        int low = Character.digit(b, 16);
        if (a > 127 || b > 127 || high < 0 || low < 0)
            throw new IllegalArgumentException("invalid hex");
        result[i / 2] = (byte) ((high << 4) | low);
    }
    return result;
}

static String encodeHex(byte[] data) {
    char[] digits = "0123456789abcdef".toCharArray();
    char[] out = new char[data.length * 2];
    for (int i = 0; i < data.length; i++) {
        int value = data[i] & 0xff;
        out[i * 2] = digits[value >>> 4];
        out[i * 2 + 1] = digits[value & 15];
    }
    return new String(out);
}

static int wrapIndex(int index, int length) {
    if (length <= 0) throw new IllegalArgumentException("length must be positive");
    return Math.floorMod(index, length);
}

import java.util.ArrayList;
import java.util.List;

static <T> List<T> rotateRight(List<T> items, int steps) {
    int size = items.size();
    if (size == 0) return new ArrayList<>();
    int shift = Math.floorMod(steps, size);
    List<T> result = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        result.add(items.get(Math.floorMod(i - shift, size)));
    }
    return result;
}

static int firstGreater(int[] sorted, int value) {
    int low = 0;
    int high = sorted.length;
    while (low < high) {
        int middle = low + (high - low) / 2;
        if (sorted[middle] <= value) low = middle + 1;
        else high = middle;
    }
    return low;
}

import java.util.List;

static String joinLines(List<String> lines) {
    return String.join("\n", lines);
}

static int countAsciiLetters(String text) {
    int count = 0;
    for (int i = 0; i < text.length(); i++) {
        char ch = text.charAt(i);
        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) count++;
    }
    return count;
}

static String repeatChar(char ch, int count) {
    if (count < 0) throw new IllegalArgumentException("negative count");
    char[] chars = new char[count];
    java.util.Arrays.fill(chars, ch);
    return new String(chars);
}

import java.util.List;

static int countPrefix(List<String> words, String prefix) {
    int count = 0;
    for (String word : words) {
        if (word != null && word.startsWith(prefix)) count++;
    }
    return count;
}

import java.util.ArrayList;
import java.util.List;

static <T> List<T> everyOther(List<T> items) {
    List<T> result = new ArrayList<>();
    for (int i = 0; i < items.size(); i += 2) result.add(items.get(i));
    return result;
}

