def test_redacts_each_nonempty_ascii_token():
    assert redact_token("token=abc123; token=Z9") == "token=[REDACTED]; token=[REDACTED]"

def test_stops_at_punctuation():
    assert redact_token("token=ab-c") == "token=[REDACTED]-c"

def test_empty_and_case_sensitive_prefix():
    assert redact_token("token= Token=abc token=") == "token= Token=abc token="

def classify_temp(c):
    if c <= 0:
        return "freezing"
    if c >= 30:
        return "hot"
    return "mild"

function shipping(weight, express) {
  if (weight <= 0) return null;
  if (express) return weight * 3 + 10;
  return weight * 2 + 5;
}
